INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (3, 'bash', 'Bash Cheatsheet', 'The GNU Bourne-Again SHell', NULL, 'Comprehensive reference for Bash syntax, scripting, and command line usage.', NULL, 'https://www.gnu.org/software/bash/manual/', '[{"label": "GNU Bash Manual", "url": "https://www.gnu.org/software/bash/manual/"}]'::jsonb, '{}'::jsonb, ARRAY['bash']::text[], '[{"icon": "⌨️", "title": "Keyboard Shortcuts", "layout": "grid", "body_cols": 1, "sections": [{"label": "Movement & Editing", "kind": "table", "copy_lines": false}]}, {"icon": "🕰️", "title": "History Expansion", "layout": "grid", "body_cols": 1, "sections": [{"label": "History References", "kind": "table", "copy_lines": false}]}, {"icon": "📦", "title": "Variables & Quoting", "layout": "grid", "body_cols": 1, "sections": [{"label": "Variables", "kind": "table", "copy_lines": false}, {"label": "Quoting", "kind": "table", "copy_lines": false}]}, {"icon": "✨", "title": "Special Parameters", "layout": "grid", "body_cols": 1, "sections": [{"label": "Script & Function Arguments", "kind": "table", "copy_lines": false}, {"label": "Process State", "kind": "table", "copy_lines": false}]}, {"icon": "✂️", "title": "Parameter Expansion", "layout": "grid", "body_cols": 1, "sections": [{"label": "Default Values & Errors", "kind": "table", "copy_lines": false}, {"label": "String Manipulation", "kind": "table", "copy_lines": false}, {"label": "Indirection & Prefix", "kind": "table", "copy_lines": false}]}, {"icon": "📚", "title": "Arrays", "layout": "grid", "body_cols": 1, "sections": [{"label": "Indexed Arrays", "kind": "table", "copy_lines": false}, {"label": "Associative Arrays (Dictionaries)", "kind": "table", "copy_lines": false}]}, {"icon": "🧮", "title": "Arithmetic", "layout": "grid", "body_cols": 1, "sections": [{"label": "Evaluation", "kind": "table", "copy_lines": false}, {"label": "Operators", "kind": "table", "copy_lines": false}]}, {"icon": "⚖️", "title": "Conditionals", "layout": "grid", "body_cols": 1, "sections": [{"label": "If / Else & Brackets", "kind": "table", "copy_lines": false}, {"label": "File Tests", "kind": "table", "copy_lines": false}, {"label": "String & Numeric Tests", "kind": "table", "copy_lines": false}, {"label": "Case Statement", "kind": "table", "copy_lines": false}]}, {"icon": "🔄", "title": "Loops", "layout": "grid", "body_cols": 1, "sections": [{"label": "For Loops", "kind": "table", "copy_lines": false}, {"label": "While / Until & Controls", "kind": "table", "copy_lines": false}]}, {"icon": "⚙️", "title": "Functions", "layout": "grid", "body_cols": 1, "sections": [{"label": "Definition & Arguments", "kind": "table", "copy_lines": false}]}, {"icon": "🔀", "title": "Redirection & Pipelines", "layout": "grid", "body_cols": 1, "sections": [{"label": "File Redirection", "kind": "table", "copy_lines": false}, {"label": "Here-Docs & Pipelines", "kind": "table", "copy_lines": false}]}, {"icon": "🧩", "title": "Substitutions & Subshells", "layout": "grid", "body_cols": 1, "sections": [{"label": "Command & Process", "kind": "table", "copy_lines": false}, {"label": "Grouping", "kind": "table", "copy_lines": false}]}, {"icon": "📂", "title": "Brace Expansion & Globbing", "layout": "grid", "body_cols": 1, "sections": [{"label": "Globbing (Pattern Matching)", "kind": "table", "copy_lines": false}, {"label": "Extended Globbing (extglob)", "kind": "table", "copy_lines": false}, {"label": "Shell Options (shopt)", "kind": "table", "copy_lines": false}]}, {"icon": "🚦", "title": "Job Control", "layout": "grid", "body_cols": 1, "sections": [{"label": "Background & Foreground", "kind": "table", "copy_lines": false}, {"label": "Process Management", "kind": "table", "copy_lines": false}]}, {"icon": "🛡️", "title": "Script Safety & Debugging", "layout": "grid", "body_cols": 1, "sections": [{"label": "Safety Options", "kind": "table", "copy_lines": false}, {"label": "Traps & Exits", "kind": "tabl