INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (5, 'find', 'find Cheatsheet', 'Search for files in a directory hierarchy', NULL, 'Comprehensive guide to GNU find, the standard Unix command for locating and acting on files based on names, types, sizes, times, and permissions.', NULL, 'https://www.gnu.org/software/findutils/manual/html_mono/find.html', '[{"label": "GNU findutils manual", "url": "https://www.gnu.org/software/findutils/manual/html_mono/find.html"}]'::jsonb, '{}'::jsonb, ARRAY['find']::text[], '[{"icon": "🔎", "title": "Basic Syntax & Directory Options", "title_accent": "Basic", "layout": "grid", "body_cols": 1, "sections": [{"label": "Basic Syntax", "kind": "table", "copy_lines": false}, {"label": "Traversal Options (must precede expression)", "kind": "table", "copy_lines": false}]}, {"icon": "🔤", "title": "Name & Path Tests", "title_accent": "Name", "layout": "grid", "body_cols": 1, "sections": [{"label": "Name Matching", "kind": "table", "copy_lines": false}, {"label": "Regular Expressions", "kind": "table", "copy_lines": false}]}, {"icon": "⚖️", "title": "Type & Size Tests", "title_accent": "Type", "layout": "grid", "body_cols": 1, "sections": [{"label": "File Types", "kind": "table", "copy_lines": false}, {"label": "Size Constraints", "kind": "table", "copy_lines": false}]}, {"icon": "⏳", "title": "Time Tests", "title_accent": "Time", "layout": "grid", "body_cols": 1, "sections": [{"label": "Time Mechanics (N interpretation)", "kind": "text", "copy_lines": false}, {"label": "Modification Time (Data changed)", "kind": "table", "copy_lines": false}, {"label": "Access & Change Time", "kind": "table", "copy_lines": false}, {"label": "Relative & Absolute Time", "kind": "table", "copy_lines": false}]}, {"icon": "🔐", "title": "Permissions & Ownership", "title_accent": "Permissions", "layout": "grid", "body_cols": 1, "sections": [{"label": "Permissions Matching", "kind": "table", "copy_lines": false}, {"label": "Ownership", "kind": "table", "copy_lines": false}]}, {"icon": "🔀", "title": "Operators & Logic", "title_accent": "Operators", "tip": "Operators connect tests. By default, expressions are ANDed.", "layout": "grid", "body_cols": 1, "sections": [{"label": "Logical Operators (Decreasing precedence)", "kind": "table", "copy_lines": false}, {"label": "Precedence Gotcha", "kind": "table", "copy_lines": false}]}, {"icon": "🚀", "title": "Actions", "title_accent": "Actions", "layout": "wide", "body_cols": 1, "sections": [{"label": "Output Actions", "kind": "table", "copy_lines": false}, {"label": "-printf Format Codes", "kind": "table", "copy_lines": false}, {"label": "Execution Actions", "kind": "table", "copy_lines": false}, {"label": "Control & Destructive Actions", "kind": "table", "copy_lines": false}]}, {"icon": "💡", "title": "Practical Examples", "title_accent": "Practical", "layout": "wide", "body_cols": 1, "sections": [{"label": "Everyday Tasks", "kind": "table", "copy_lines": false}]}]'::jsonb);
