INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (7, 'mongodb', 'MongoDB Cheatsheet', 'mongosh client, query language & database tools', NULL, 'Comprehensive MongoDB cheatsheet covering mongosh connection, shell helpers, CRUD operations, query & update operators, aggregation pipeline, indexes, and database tools.', NULL, 'https://www.mongodb.com/docs/manual/', '[{"label": "mongodb.com/docs/shell", "url": "https://www.mongodb.com/docs/mongodb-shell/"}, {"label": "mongodb.com/docs/manual", "url": "https://www.mongodb.com/docs/manual/reference/operator/"}, {"label": "mongodb.com/docs/tools", "url": "https://www.mongodb.com/docs/database-tools/"}]'::jsonb, '{}'::jsonb, ARRAY['mongo', 'mongodb', 'mongosh']::text[], '[{"icon": "🔌", "title": "Connect & Helpers", "title_accent": "Connect", "layout": "grid", "body_cols": 1, "sections": [{"label": "Connection (mongosh)", "kind": "table", "copy_lines": false}, {"label": "Shell Helpers", "kind": "table", "copy_lines": false}]}, {"icon": "🗄️", "title": "Databases & Collections", "title_accent": "Databases", "layout": "grid", "body_cols": 1, "sections": [{"label": "Management", "kind": "table", "copy_lines": false}]}, {"icon": "📝", "title": "CRUD: Create, Update, Delete", "title_accent": "CRUD", "layout": "grid", "body_cols": 1, "sections": [{"label": "Insert", "kind": "table", "copy_lines": false}, {"label": "Update & Replace", "kind": "table", "copy_lines": false}, {"label": "Delete", "kind": "table", "copy_lines": false}]}, {"icon": "🔍", "title": "Queries & Cursors", "title_accent": "Queries", "layout": "grid", "body_cols": 1, "sections": [{"label": "Find & Read Methods", "kind": "table", "copy_lines": false}, {"label": "Projection Array Operators", "kind": "table", "copy_lines": false}, {"label": "Cursor Options", "kind": "table", "copy_lines": false}, {"label": "Counting & Distinct", "kind": "table", "copy_lines": false}]}, {"icon": "❓", "title": "Query Operators", "title_accent": "Query", "layout": "wide", "body_cols": 1, "sections": [{"label": "Comparison & Logical", "kind": "table", "copy_lines": false}, {"label": "Element, Array & Evaluation", "kind": "table", "copy_lines": false}, {"label": "Geospatial", "kind": "table", "copy_lines": false}]}, {"icon": "🔄", "title": "Update Operators", "title_accent": "Update", "layout": "wide", "body_cols": 1, "sections": [{"label": "Fields", "kind": "table", "copy_lines": false}, {"label": "Arrays", "kind": "table", "copy_lines": false}]}, {"icon": "📊", "title": "Aggregation Pipeline", "title_accent": "Aggregation", "layout": "wide", "body_cols": 1, "sections": [{"label": "Core Stages", "kind": "table", "copy_lines": false}, {"label": "Advanced Stages", "kind": "table", "copy_lines": false}, {"label": "Accumulators & Expressions", "kind": "table", "copy_lines": false}]}, {"icon": "⚡", "title": "Indexes & Performance", "title_accent": "Indexes", "layout": "grid", "body_cols": 1, "sections": [{"label": "Index Management", "kind": "table", "copy_lines": false}, {"label": "Text & Wildcard Indexes", "kind": "table", "copy_lines": false}, {"label": "Query Diagnostics", "kind": "table", "copy_lines": false}]}, {"icon": "🛠️", "title": "Admin, Auth & Diagnostics", "title_accent": "Admin", "layout": "grid", "body_cols": 1, "sections": [{"label": "Schema & Transactions", "kind": "table", "copy_lines": false}, {"label": "Users & Roles", "kind": "table", "copy_lines": false}, {"label": "Diagnostics & Server", "kind": "table", "copy_lines": false}]}, {"icon": "🧰", "title": "Database Tools", "title_accent": "Tools", "layout": "wide", "body_cols": 1, "sections": [{"label": "Export & Import Data", "kind": "table", "copy_lines": false}, {"label": "Common Tool Flags", "kind": "table", "copy_lines": false}]}]'::jsonb);
