INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (10, 'psql', 'PostgreSQL Cheatsheet', 'psql client, PostgreSQL SQL & Admin', NULL, 'Comprehensive PostgreSQL cheatsheet: psql meta-commands, SQL data types, JSONB, array operators, window functions, and admin queries.', NULL, 'https://www.postgresql.org/docs/current/', '[{"label": "postgresql.org/docs", "url": "https://www.postgresql.org/docs/current/"}]'::jsonb, '{}'::jsonb, ARRAY['pg', 'postgres', 'postgresql', 'psql']::text[], '[{"icon": "🔌", "title": "Connect & Session", "title_accent": "Connect", "layout": "grid", "body_cols": 1, "sections": [{"label": "Connection Commands", "kind": "table", "copy_lines": false}, {"label": "Environment Variables", "kind": "table", "copy_lines": false}, {"label": "Config Files", "kind": "table", "copy_lines": false}]}, {"icon": "⚡", "title": "psql Meta-Commands", "title_accent": "Meta-Commands", "layout": "grid", "body_cols": 1, "sections": [{"label": "Information & Navigation", "kind": "table", "copy_lines": false}, {"label": "List Database Objects", "kind": "table", "copy_lines": false}, {"label": "Formatting & I/O", "kind": "table", "copy_lines": false}, {"label": "Execution & Editing", "kind": "table", "copy_lines": false}]}, {"icon": "🗄️", "title": "Databases & Schemas", "title_accent": "Databases", "layout": "grid", "body_cols": 1, "sections": [{"label": "Databases", "kind": "table", "copy_lines": false}, {"label": "Schemas", "kind": "table", "copy_lines": false}]}, {"icon": "🏗️", "title": "Tables & Constraints", "title_accent": "Tables", "layout": "grid", "body_cols": 1, "sections": [{"label": "Create Table", "kind": "table", "copy_lines": false}, {"label": "Column Types & Constraints", "kind": "table", "copy_lines": false}, {"label": "Alter Table", "kind": "table", "copy_lines": false}]}, {"icon": "🔠", "title": "Data Types", "title_accent": "Data", "layout": "grid", "body_cols": 1, "sections": [{"label": "Common Types", "kind": "table", "copy_lines": false}, {"label": "Advanced Types", "kind": "table", "copy_lines": false}]}, {"icon": "📝", "title": "CRUD & Filtering", "title_accent": "CRUD", "layout": "grid", "body_cols": 1, "sections": [{"label": "Write Data", "kind": "table", "copy_lines": false}, {"label": "Filtering (WHERE)", "kind": "table", "copy_lines": false}]}, {"icon": "🔗", "title": "Joins, Aggregates & CTEs", "title_accent": "Joins", "layout": "grid", "body_cols": 1, "sections": [{"label": "Joins", "kind": "table", "copy_lines": false}, {"label": "Aggregations", "kind": "table", "copy_lines": false}, {"label": "Subqueries & CTEs", "kind": "table", "copy_lines": false}]}, {"icon": "🪟", "title": "Window Functions", "title_accent": "Window", "layout": "grid", "body_cols": 1, "sections": [{"label": "Window Functions", "kind": "table", "copy_lines": false}]}, {"icon": "🛠️", "title": "Functions & Triggers", "title_accent": "Functions", "layout": "grid", "body_cols": 1, "sections": [{"label": "String Functions", "kind": "table", "copy_lines": false}, {"label": "Date/Time Functions", "kind": "table", "copy_lines": false}, {"label": "Utility Functions", "kind": "table", "copy_lines": false}, {"label": "Custom Functions & Triggers", "kind": "table", "copy_lines": false}]}, {"icon": "📦", "title": "JSONB & Arrays", "title_accent": "JSONB", "layout": "grid", "body_cols": 1, "sections": [{"label": "JSONB Operators", "kind": "table", "copy_lines": false}, {"label": "JSONB Functions", "kind": "table", "copy_lines": false}, {"label": "Array Operators", "kind": "table", "copy_lines": false}]}, {"icon": "🔍", "title": "Indexes & Views", "title_accent": "Indexes", "layout": "grid", "body_cols": 1, "sections": [{"label": "Indexes", "kind": "table", "copy_lines": false}, {"label": "Views & Materialized Views", "kind": "table", "copy_lines": false}]}, {"icon": "⚙️", "title": "Admin & Maintenance", "title_accent": "Admin", "layout": "grid", "body_cols": 1, "sections": [{"label": "Query Analysis", "kind": "table", "copy_lines": false}, {"label": "Maintenance", "kind": "table", "copy_lines": false}, {"label": "Server & Activity", "kind": "table", "copy_lines": false}]}, {"icon": "🛡️", "title": "Roles, Backup & Transactions", "title_accent": "Roles", "layout": "grid", "body_cols": 1, "sections": [{"label": "Roles & Permissions", "kind": "table", "copy_lines": false}, {"label": "Transactions", "kind": "table", "copy_lines": false}, {"label": "Backup, Restore & Extensions", "kind": "table", "copy_lines": false}]}]'::jsonb);
