INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (11, 'sed', 'sed Cheatsheet', 'Stream Editor for filtering and transforming text', NULL, 'Comprehensive cheatsheet for sed, covering command line options, addresses, substitution, advanced commands, hold space, and classic one-liners.', NULL, 'https://www.gnu.org/software/sed/manual/sed.html', '[{"label": "GNU sed manual", "url": "https://www.gnu.org/software/sed/manual/sed.html"}, {"label": "sed man page", "url": "https://linux.die.net/man/1/sed"}]'::jsonb, '{}'::jsonb, ARRAY['sed']::text[], '[{"icon": "🚀", "title": "Invocation & Options", "title_accent": "Invocation", "layout": "grid", "body_cols": 1, "sections": [{"label": "Basic options", "kind": "table", "copy_lines": false}]}, {"icon": "📍", "title": "Addresses & Ranges", "title_accent": "Addresses", "layout": "grid", "body_cols": 1, "sections": [{"label": "Addresses", "kind": "table", "copy_lines": false}]}, {"icon": "🔄", "title": "Substitute Command (s)", "title_accent": "Substitute", "layout": "grid", "body_cols": 1, "sections": [{"label": "Basic syntax", "kind": "table", "copy_lines": false}, {"label": "Flags", "kind": "table", "copy_lines": false}, {"label": "Case conversion (GNU)", "kind": "table", "copy_lines": false}]}, {"icon": "🛠️", "title": "Basic Commands", "title_accent": "Commands", "layout": "grid", "body_cols": 1, "sections": [{"label": "Printing & Deleting", "kind": "table", "copy_lines": false}, {"label": "Inserting & Changing", "kind": "table", "copy_lines": false}, {"label": "File I/O", "kind": "table", "copy_lines": false}]}, {"icon": "🧠", "title": "Advanced Commands", "title_accent": "Advanced", "layout": "grid", "body_cols": 1, "sections": [{"label": "Multi-line pattern space", "kind": "table", "copy_lines": false}, {"label": "Hold space", "kind": "table", "copy_lines": false}, {"label": "Hold space classics", "kind": "table", "copy_lines": false}, {"label": "GNU extensions", "kind": "table", "copy_lines": false}]}, {"icon": "🔀", "title": "Flow Control & Scripts", "title_accent": "Flow", "layout": "grid", "body_cols": 1, "sections": [{"label": "Branching", "kind": "table", "copy_lines": false}, {"label": "Scripts", "kind": "table", "copy_lines": false}, {"label": "In-place across files", "kind": "table", "copy_lines": false}]}, {"icon": "🧩", "title": "Regex & Patterns", "title_accent": "Regex", "layout": "grid", "body_cols": 1, "sections": [{"label": "BRE vs ERE", "kind": "table", "copy_lines": false}]}, {"icon": "✨", "title": "Classic One-Liners", "title_accent": "One-Liners", "layout": "grid", "body_cols": 1, "sections": [{"label": "Text manipulation", "kind": "table", "copy_lines": false}, {"label": "Extract & Print", "kind": "table", "copy_lines": false}, {"label": "Specific Replacements", "kind": "table", "copy_lines": false}]}]'::jsonb);
