INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (12, 'tar', 'tar Cheatsheet', 'Archive, compress, and extract files', NULL, 'Comprehensive reference for tar, gzip, zip, and other compression utilities. Covers basic operations, file filtering, compression algorithms, and advanced tar recipes.', NULL, 'https://www.gnu.org/software/tar/manual/tar.html', '[{"label": "GNU tar manual", "url": "https://www.gnu.org/software/tar/manual/tar.html"}]'::jsonb, '{}'::jsonb, ARRAY['gunzip', 'gzip', 'tar', 'unzip', 'zip']::text[], '[{"icon": "📦", "title": "Operation Modes", "title_accent": "Operation", "layout": "grid", "body_cols": 1, "sections": [{"label": "Main Operations", "kind": "table", "columns": ["Command", "Description"], "copy_lines": false}]}, {"icon": "⚙️", "title": "Common Options", "title_accent": "Common", "layout": "grid", "body_cols": 1, "sections": [{"label": "General", "kind": "table", "copy_lines": false}, {"label": "Compression algorithms", "kind": "table", "copy_lines": false}, {"label": "Permissions & Ownership", "kind": "table", "copy_lines": false}]}, {"icon": "🛡️", "title": "Extraction Options", "title_accent": "Extraction", "layout": "grid", "body_cols": 1, "sections": [{"label": "Overwrite Control", "kind": "table", "copy_lines": false}]}, {"icon": "🔍", "title": "Filters & Selection", "title_accent": "Filters", "layout": "grid", "body_cols": 1, "sections": [{"label": "Exclusions", "kind": "table", "copy_lines": false}, {"label": "Inclusions & Paths", "kind": "table", "copy_lines": false}]}, {"icon": "🛠️", "title": "Advanced Tar", "title_accent": "Advanced", "layout": "grid", "body_cols": 1, "sections": [{"label": "Transformation & Backup", "kind": "table", "copy_lines": false}, {"label": "Useful Recipes", "kind": "table", "copy_lines": false}]}, {"icon": "🗜️", "title": "Other Compressors", "title_accent": "Compressors", "layout": "grid", "body_cols": 1, "sections": [{"label": "gzip / gunzip / zcat", "kind": "table", "copy_lines": false}, {"label": "zip / unzip", "kind": "table", "copy_lines": false}, {"label": "bzip2 / xz / zstd", "kind": "table", "copy_lines": false}]}]'::jsonb);
