INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (13, 'xargs', 'xargs Cheatsheet', 'Build and execute command lines from standard input', NULL, 'Comprehensive reference for xargs: splitting input, batching arguments, parallel execution, and safe filename handling.', NULL, 'https://www.gnu.org/software/findutils/manual/html_node/find_html/Invoking-xargs.html', '[{"label": "GNU findutils (xargs)", "url": "https://www.gnu.org/software/findutils/manual/html_node/find_html/Invoking-xargs.html"}]'::jsonb, '{}'::jsonb, ARRAY['xargs']::text[], '[{"icon": "📥", "title": "Input & Splitting", "layout": "grid", "body_cols": 1, "sections": [{"kind": "text", "copy_lines": false}, {"kind": "table", "copy_lines": false}]}, {"icon": "⚙️", "title": "Controlling Execution", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"icon": "⚡", "title": "Interactive & Parallel", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"icon": "💡", "title": "Patterns & Practical Examples", "layout": "wide", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"icon": "🛑", "title": "Exit Status & Info", "layout": "grid", "body_cols": 1, "sections": [{"kind": "rows", "copy_lines": false}, {"kind": "table", "copy_lines": false}]}]'::jsonb);
INSERT INTO entries (sheet_id, card_pos, section_pos, position, card, section, kind, command, description, details, example, danger, lang, display, embed_text, content_hash, description_vi, embed_text_vi, content_hash_vi) VALUES (13, 1, 1, 1, 'Input & Splitting', NULL, 'note', NULL, 'By default, xargs splits on spaces, tabs, and newlines. It also processes single quotes, double quotes, and backslashes, which can cause errors if input contains unmatched quotes. Use -0 or -d to disable quote processing.', NULL, NULL, NULL, NULL, '{}'::jsonb, 'xargs › Input & Splitting
